#!/usr/bin/env python3
"""Compute ground truth for the CSX-194_Q2 fire-weather phase ledger."""

from __future__ import annotations

import json
from pathlib import Path


TASK_ID = "CSX-194_Q2"
EVENT_ID = "CSX-194"
TARGET_FAMILY = "candidate_explanation_score_ledger"
REPO_ROOT = Path(__file__).resolve().parents[3]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT_PATH = Path(__file__).resolve().with_name("computed_gt.json")

SOURCE_FILES = [
    "metadata/event.json",
    "data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json",
    "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
]

PERIODS = [
    ("baseline_watch", "2019-08-18", "2019-08-31"),
    ("initial_spread", "2019-09-01", "2019-09-16"),
    ("later_renewed_spread", "2019-09-17", "2019-10-16"),
]

PERIOD_SCORE_FORMULA = (
    "0.35*dry_day_fraction + 0.25*zero_rain_fraction + "
    "0.20*(max_daily_high_temperature_c/30) + 0.20*(max_daily_wind_speed_kmh/35)"
)
SINGLE_DAY_SCORE_FORMULA = "0.45*(temperature_c/30) + 0.35*(wind_kmh/35) + 0.20 if precipitation is 0 mm"

RUBRIC_CRITERIA = [
    {
        "name": "Final ledger answer",
        "points": 4,
        "description": (
            "Returns compact JSON with the requested fields and the exact final label "
            "initial_spread_peak_with_later_rekindling_secondary."
        ),
        "partial_credit": "Award 1-3 points for a mostly complete JSON object with a partially correct final label.",
    },
    {
        "name": "Period metric computation",
        "points": 5,
        "description": (
            "Correctly computes each period's precipitation total, dry-day count, zero-rain-day count, maximum "
            "temperature, maximum wind, and score with units and rounding."
        ),
        "partial_credit": "Award 1-4 points when some period values are correct but counts, units, or rounding are incomplete.",
    },
    {
        "name": "Window score comparison and threshold decision",
        "points": 4,
        "description": (
            "Identifies initial_spread as dominant, later_renewed_spread as close secondary, and baseline_watch as baseline, and concludes that "
            "the later period is not rain-suppressed because its score remains close to the top score."
        ),
        "partial_credit": "Award 1-3 points for a correct score comparison without a clear rain-suppression rejection, or vice versa.",
    },
    {
        "name": "Later single-day warning",
        "points": 3,
        "description": (
            "Identifies 2019-10-06 as the strongest post-2019-09-16 warning day with 27.5 C, 0.0 mm precipitation, "
            "28.4 km/h wind, and score 0.896."
        ),
        "partial_credit": "Award 1-2 points for the right date with incomplete values or the right formula with the wrong date.",
    },
    {
        "name": "Burn-signal consistency check",
        "points": 2,
        "description": (
            "Uses dNBR mean 0.123 and maximum 0.974 to support burn disturbance while avoiding a claim of uniform "
            "severe burning."
        ),
        "partial_credit": "Award 1 point for citing positive dNBR without the maximum value or overclaim caution.",
    },
    {
        "name": "Bounded mechanism interpretation",
        "points": 1,
        "description": "Keeps the mechanism statement as a short consequence of the score ledger.",
        "partial_credit": "Award 0.5 points for a mostly concise interpretation with minor excess narrative.",
    },
    {
        "name": "No extra overclaim",
        "points": 1,
        "description": (
            "Avoids extra action claims, external loss claims, and treating the benchmark score as an official "
            "fire-danger index."
        ),
        "partial_credit": "Award 0.5 points for one minor extra embellishment that does not change the answer.",
    },
]


def read_json(rel_path: str) -> dict:
    return json.loads((PACKAGE_ROOT / rel_path).read_text(encoding="utf-8"))


def round_float(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def daily_rows(open_meteo: dict) -> list[dict]:
    daily = open_meteo["daily"]
    return [
        {
            "date": date,
            "temperature_2m_max_c": float(daily["temperature_2m_max"][idx]),
            "precipitation_sum_mm": float(daily["precipitation_sum"][idx]),
            "wind_speed_10m_max_kmh": float(daily["wind_speed_10m_max"][idx]),
        }
        for idx, date in enumerate(daily["time"])
    ]


def period_rows(rows: list[dict], start: str, end: str) -> list[dict]:
    selected = [row for row in rows if start <= row["date"] <= end]
    if not selected:
        raise ValueError(f"No weather rows for {start} to {end}")
    return selected


def period_summary(rows: list[dict], label: str, start: str, end: str) -> dict:
    selected = period_rows(rows, start, end)
    day_count = len(selected)
    dry_days = sum(1 for row in selected if row["precipitation_sum_mm"] < 1.0)
    zero_rain_days = sum(1 for row in selected if row["precipitation_sum_mm"] == 0.0)
    max_temp = max(row["temperature_2m_max_c"] for row in selected)
    max_wind = max(row["wind_speed_10m_max_kmh"] for row in selected)
    dry_fraction = dry_days / day_count
    zero_rain_fraction = zero_rain_days / day_count
    score = (
        0.35 * dry_fraction
        + 0.25 * zero_rain_fraction
        + 0.20 * (max_temp / 30.0)
        + 0.20 * (max_wind / 35.0)
    )

    return {
        "label": label,
        "start": start,
        "end": end,
        "day_count": day_count,
        "total_precipitation_mm": round_float(sum(row["precipitation_sum_mm"] for row in selected), 1),
        "dry_days_lt_1mm": dry_days,
        "zero_rain_days": zero_rain_days,
        "dry_day_fraction": round_float(dry_fraction, 3),
        "zero_rain_day_fraction": round_float(zero_rain_fraction, 3),
        "maximum_daily_high_temperature_c": round_float(max_temp, 1),
        "maximum_daily_wind_speed_kmh": round_float(max_wind, 1),
        "score": round_float(score, 3),
    }


def single_day_warning(row: dict) -> float:
    zero_rain_bonus = 0.20 if row["precipitation_sum_mm"] == 0.0 else 0.0
    return (
        0.45 * (row["temperature_2m_max_c"] / 30.0)
        + 0.35 * (row["wind_speed_10m_max_kmh"] / 35.0)
        + zero_rain_bonus
    )


def strongest_later_day(rows: list[dict]) -> dict:
    later_rows = [row for row in rows if row["date"] >= "2019-09-17"]
    if not later_rows:
        raise ValueError("No weather rows after 2019-09-16")
    strongest = max(later_rows, key=single_day_warning)
    return {
        "date": strongest["date"],
        "temperature_c": round_float(strongest["temperature_2m_max_c"], 1),
        "precipitation_mm": round_float(strongest["precipitation_sum_mm"], 1),
        "wind_kmh": round_float(strongest["wind_speed_10m_max_kmh"], 1),
        "score": round_float(single_day_warning(strongest), 3),
    }


def compact_period_scores(summaries: list[dict]) -> dict:
    return {
        item["label"]: {
            "total_precipitation_mm": item["total_precipitation_mm"],
            "dry_day_count": item["dry_days_lt_1mm"],
            "zero_rain_day_count": item["zero_rain_days"],
            "maximum_daily_high_temperature_c": item["maximum_daily_high_temperature_c"],
            "maximum_daily_wind_speed_kmh": item["maximum_daily_wind_speed_kmh"],
            "score": item["score"],
        }
        for item in summaries
    }


def main() -> None:
    event = read_json("metadata/event.json")
    open_meteo = read_json("data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json")
    dnbr = read_json("data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json")

    rows = daily_rows(open_meteo)
    summaries = [period_summary(rows, label, start, end) for label, start, end in PERIODS]
    score_sequence = sorted(summaries, key=lambda item: item["score"], reverse=True)
    later_warning = strongest_later_day(rows)
    dnbr_stats = dnbr["stats"]
    dnbr_mean = round_float(dnbr_stats["sentinel2_dnbr_mean"], 3)
    dnbr_max = round_float(dnbr_stats["sentinel2_dnbr_max"], 3)
    burn_state = "positive_mean_burn_disturbance" if dnbr_mean > 0 else "no_positive_mean_burn_disturbance"
    final_label = "initial_spread_peak_with_later_rekindling_secondary"

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "period_scores": compact_period_scores(summaries),
            "score_comparison": {
                "dominant_period": score_sequence[0]["label"],
                "secondary_period": score_sequence[1]["label"],
                "baseline_period": score_sequence[2]["label"],
                "gap_top_minus_second": round_float(score_sequence[0]["score"] - score_sequence[1]["score"], 3),
            },
            "strongest_later_day": later_warning,
            "burn_signal": {
                "dnbr_mean": dnbr_mean,
                "dnbr_max": dnbr_max,
                "state": burn_state,
                "positive_mean_supports_burn_disturbance": dnbr_mean > 0,
            },
            "final_label": final_label,
        },
        "numeric_tolerances": {
            "scores": 0.002,
            "weather": 0.1,
        },
        "key_values": {
            "event_metadata": {
                "package_id": event["package_id"],
                "event_name": event["event_name"],
                "hazard_label": event["hazard_label"],
                "scale": event["scale"],
            },
            "target_family": TARGET_FAMILY,
            "period_score_formula": PERIOD_SCORE_FORMULA,
            "single_day_score_formula": SINGLE_DAY_SCORE_FORMULA,
            "weather_source_scope": (
                "The Open-Meteo daily record is a package point-weather phase diagnostic, "
                "not a complete southeastern-Australia regional weather field."
            ),
            "period_summaries": summaries,
            "score_sequence": [
                {
                    "position": idx + 1,
                    "label": item["label"],
                    "score": item["score"],
                }
                for idx, item in enumerate(score_sequence)
            ],
            "score_gap_top_minus_second": round_float(score_sequence[0]["score"] - score_sequence[1]["score"], 3),
            "strongest_post_sep16_single_day_warning": later_warning,
            "burn_signal": {
                "sentinel2_pre_window": dnbr["windows"]["pre"],
                "sentinel2_post_window": dnbr["windows"]["post"],
                "sentinel2_dnbr_mean": dnbr_mean,
                "sentinel2_dnbr_max": dnbr_max,
                "state": burn_state,
                "interpretation": (
                    "Positive mean dNBR supports burn disturbance; the maximum indicates localized high "
                    "disturbance but does not imply uniform severe burning."
                ),
            },
            "decision_rule": (
                "Use the highest period score as the dominant phase. If the post-2019-09-16 period remains "
                "within 0.03 of the top score or contains the strongest later zero-rain hot-windy day, retain "
                "later renewed-spread concern as secondary."
            ),
        },
        "rubric": {
            "total_points": 20,
            "criteria": RUBRIC_CRITERIA,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": (
                "Weather values come from the package daily weather record and dNBR values come from the "
                "Sentinel-2 summary. The score is a benchmark diagnostic ledger, not an official fire-danger index."
            ),
        },
    }

    OUT_PATH.write_text(json.dumps(result, indent=2, sort_keys=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
